import{_ as t,o as a,c as o,a4 as r}from"./chunks/framework.9tZL7ZIQ.js";const b=JSON.parse('{"title":"1993年 · 护城河与风险","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1993年.md","filePath":"05_quotes/by-year/1993年.md"}'),l={name:"05_quotes/by-year/1993年.md"};function s(u,e,c,_,h,q){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="_1993年-·-护城河与风险" tabindex="-1">1993年 · 护城河与风险 <a class="header-anchor" href="#_1993年-·-护城河与风险" aria-label="Permalink to &quot;1993年 · 护城河与风险&quot;">​</a></h1><blockquote><p>短期来看，市场是一台投票机——反映的是只需要资金、不需要智慧或情绪稳定的选民登记测试——但长期来看，市场是一台称重机。——巴菲特（63岁）</p></blockquote><p>本页收录1993年致股东信中的经典语录。本年巴菲特系统批判了学术界用贝塔系数定义投资风险的谬误，提出了基于企业经济特征的真正风险衡量框架，并以可口可乐和吉列为范例阐述了&quot;护城河&quot;理念。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>近似正确胜过精确错误。</p></blockquote><blockquote><p>在商业中有意义的事情在股票中也有意义：投资者通常应该像所有者拥有整个企业那样坚韧地持有一家杰出企业的一小部分。</p></blockquote><blockquote><p>其品牌名称的影响力、产品的特质和分销系统的实力，为它们的经济城堡筑起了一道保护性的护城河。相比之下，普通公司每天都在没有任何这种保护的情况下进行竞争。</p></blockquote><blockquote><p>如果你走在错误的路上，奔跑是没有用的。</p></blockquote><blockquote><p>我们坚持做简单的事情。当一根针就摆在眼前时，为什么要在大海捞针呢？</p></blockquote><blockquote><p>剥离一个既可理解又持久卓越的业务权益通常是愚蠢的。这种类型的业务利益太难被替代。</p></blockquote><blockquote><p>真正的投资者是欢迎波动的……剧烈波动的市场意味着优质企业会周期性地被赋予非理性的低价。不可能认为这种价格的存在会增加完全自由地忽略市场或利用其愚蠢的投资者所面临的风险。</p></blockquote><blockquote><p>如果你是一个有所知的投资者，能够理解商业经济，并能找到五到十家定价合理且具有重要长期竞争优势的公司，传统的多元化对你来说就没有意义。它只会损害你的业绩并增加你的风险。</p></blockquote><blockquote><p>当一根针就摆在眼前时，为什么要在大海捞针呢？</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1993年伯克希尔每股账面价值增长14.3%，收购了德克斯特鞋业，保险业务浮存金增长至26亿美元且成本为负。巴菲特在本年信中用大量篇幅驳斥了贝塔系数作为风险衡量标准的主流学术观点，并以可口可乐和吉列为案例阐述了持久竞争优势即&quot;护城河&quot;的概念。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-1993年-翻译-·-01-letters-1993年-核心总结-·-01-letters-1993年-思维导图" tabindex="-1"><a href="/01_letters/1993年/翻译">01_letters/1993年/翻译</a> · <a href="/01_letters/1993年/核心总结">01_letters/1993年/核心总结</a> · <a href="/01_letters/1993年/思维导图">01_letters/1993年/思维导图</a> <a class="header-anchor" href="#_01-letters-1993年-翻译-·-01-letters-1993年-核心总结-·-01-letters-1993年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/1993年/翻译]] · [[→ 核心总结|01_letters/1993年/核心总结]] · [[→ 思维导图|01_letters/1993年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/1993年/翻译">/01_letters/1993年/翻译</a></li></ul>',22)])])}const p=t(l,[["render",s]]);export{b as __pageData,p as default};
